"use client"

import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card"
import {
  LineChart,
  Line,
  BarChart,
  Bar,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
  ResponsiveContainer,
} from "recharts"

interface ProgressChartProps {
  type?: "line" | "bar"
}

export function ProgressChart({ type = "line" }: ProgressChartProps) {
  const data = [
    { week: "Week 1", accuracy: 65, fluency: 62, speed: 70, comprehension: 68 },
    { week: "Week 2", accuracy: 70, fluency: 68, speed: 72, comprehension: 71 },
    { week: "Week 3", accuracy: 75, fluency: 74, speed: 78, comprehension: 76 },
    { week: "Week 4", accuracy: 82, fluency: 80, speed: 85, comprehension: 82 },
  ]

  return (
    <Card>
      <CardHeader>
        <CardTitle>Your Progress This Month</CardTitle>
        <CardDescription>Track your improvement across all skills</CardDescription>
      </CardHeader>
      <CardContent>
        <ResponsiveContainer width="100%" height={300}>
          {type === "line" ? (
            <LineChart data={data} margin={{ top: 5, right: 30, left: 0, bottom: 5 }}>
              <CartesianGrid strokeDasharray="3 3" />
              <XAxis dataKey="week" />
              <YAxis />
              <Tooltip />
              <Legend />
              <Line type="monotone" dataKey="accuracy" stroke="hsl(var(--chart-1))" strokeWidth={2} />
              <Line type="monotone" dataKey="fluency" stroke="hsl(var(--chart-2))" strokeWidth={2} />
              <Line type="monotone" dataKey="speed" stroke="hsl(var(--chart-3))" strokeWidth={2} />
              <Line type="monotone" dataKey="comprehension" stroke="hsl(var(--chart-4))" strokeWidth={2} />
            </LineChart>
          ) : (
            <BarChart data={data} margin={{ top: 5, right: 30, left: 0, bottom: 5 }}>
              <CartesianGrid strokeDasharray="3 3" />
              <XAxis dataKey="week" />
              <YAxis />
              <Tooltip />
              <Legend />
              <Bar dataKey="accuracy" fill="hsl(var(--chart-1))" />
              <Bar dataKey="fluency" fill="hsl(var(--chart-2))" />
              <Bar dataKey="speed" fill="hsl(var(--chart-3))" />
              <Bar dataKey="comprehension" fill="hsl(var(--chart-4))" />
            </BarChart>
          )}
        </ResponsiveContainer>
      </CardContent>
    </Card>
  )
}
