"use client"

import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card"
import { Progress } from "@/components/ui/progress"
import { TrendingUp, Calendar, Target, Zap } from "lucide-react"

export function QuickStats() {
  const stats = [
    { label: "Tests This Month", value: 12, icon: Calendar, color: "text-blue-500" },
    { label: "Average Score", value: 81, unit: "%", icon: TrendingUp, color: "text-green-500" },
    { label: "Current Streak", value: 7, unit: " days", icon: Zap, color: "text-orange-500" },
    { label: "Best Score", value: 95, unit: "%", icon: Target, color: "text-purple-500" },
  ]

  return (
    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
      {stats.map((stat, i) => {
        const Icon = stat.icon
        return (
          <Card key={i}>
            <CardHeader className="pb-2">
              <div className="flex items-center justify-between">
                <CardTitle className="text-sm font-medium text-muted-foreground">{stat.label}</CardTitle>
                <Icon className={`w-4 h-4 ${stat.color}`} />
              </div>
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold">
                {stat.value}
                {stat.unit && <span className="text-lg">{stat.unit}</span>}
              </div>
              {stat.label === "Average Score" && <Progress value={stat.value} className="mt-2" />}
            </CardContent>
          </Card>
        )
      })}
    </div>
  )
}
