"use client"

import type React from "react"

import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card"
import { Trophy, Star, Zap, Flame, Target, BookOpen } from "lucide-react"

interface Achievement {
  id: string
  name: string
  description: string
  icon: React.ReactNode
  unlocked: boolean
  progress?: number
}

export function AchievementBadges() {
  const achievements: Achievement[] = [
    {
      id: "starter",
      name: "Getting Started",
      description: "Complete your first assessment",
      icon: <Star className="w-5 h-5" />,
      unlocked: true,
    },
    {
      id: "streak",
      name: "On Fire",
      description: "Complete 7 assessments in a row",
      icon: <Flame className="w-5 h-5" />,
      unlocked: true,
    },
    {
      id: "accuracy",
      name: "Sharp Shooter",
      description: "Score 90% accuracy",
      icon: <Target className="w-5 h-5" />,
      unlocked: false,
      progress: 82,
    },
    {
      id: "fluency",
      name: "Fluent Speaker",
      description: "Achieve 85% fluency score",
      icon: <Zap className="w-5 h-5" />,
      unlocked: true,
    },
    {
      id: "reader",
      name: "Avid Reader",
      description: "Complete 25 passage assessments",
      icon: <BookOpen className="w-5 h-5" />,
      unlocked: false,
      progress: 18,
    },
    {
      id: "champion",
      name: "Reading Champion",
      description: "Average score above 85%",
      icon: <Trophy className="w-5 h-5" />,
      unlocked: false,
      progress: 78,
    },
  ]

  return (
    <Card>
      <CardHeader>
        <CardTitle>Achievements</CardTitle>
        <CardDescription>Unlock badges as you progress</CardDescription>
      </CardHeader>
      <CardContent>
        <div className="grid grid-cols-2 md:grid-cols-3 gap-4">
          {achievements.map((achievement) => (
            <div
              key={achievement.id}
              className={`flex flex-col items-center gap-2 p-3 rounded-lg border transition-all ${
                achievement.unlocked
                  ? "bg-gradient-to-br from-primary/10 to-accent/10 border-primary/30"
                  : "bg-muted border-border opacity-60"
              }`}
            >
              <div className={achievement.unlocked ? "text-primary" : "text-muted-foreground"}>{achievement.icon}</div>
              <div className="text-center">
                <p className="text-xs font-semibold line-clamp-1">{achievement.name}</p>
                {!achievement.unlocked && achievement.progress !== undefined && (
                  <div className="mt-1 w-full">
                    <div className="text-xs text-muted-foreground mb-1">{achievement.progress}%</div>
                    <div className="w-full h-1 bg-border rounded-full overflow-hidden">
                      <div
                        className="h-full bg-primary transition-all"
                        style={{ width: `${achievement.progress}%` }}
                      ></div>
                    </div>
                  </div>
                )}
              </div>
            </div>
          ))}
        </div>
      </CardContent>
    </Card>
  )
}
